uid)","before":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}","target":"{postgres=X/postgres,service_role=X/postgres}","revoke_roles":["authenticated"],"grant_roles":[]},{"kind":"function","identity":"public.select_idea_for_slot(p_slot_id uuid)","before":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}","target":"{postgres=X/postgres,service_role=X/postgres}","revoke_roles":["authenticated"],"grant_roles":[]},{"kind":"function","identity":"public.set_updated_at()","before":"{postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}","target":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}","revoke_roles":["anon"],"grant_roles":[]},{"kind":"function","identity":"public.settle_completed_blocked_daily_siblings(p_limit integer)","before":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}","target":"{postgres=X/postgres,service_role=X/postgres}","revoke_roles":["authenticated"],"grant_roles":[]},{"kind":"function","identity":"public.stage_video_candidate_revision(p_candidate_id uuid)","before":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}","target":"{postgres=X/postgres,service_role=X/postgres}","revoke_roles":["authenticated"],"grant_roles":[]},{"kind":"function","identity":"public.stamp_media_purpose_from_brief()","before":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}","target":"{postgres=X/postgres,service_role=X/postgres}","revoke_roles":["authenticated"],"grant_roles":[]},{"kind":"function","identity":"public.start_client_launch_package(p_campaign_id uuid, p_idempotency_key text, p_deadline_at timestamp with time zone)","before":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}","target":"{postgres=X/postgres,service_role=X/postgres}","revoke_roles":["authenticated"],"grant_roles":[]},{"kind":"function","identity":"public.sweep_expired_proof_placements()","before":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}","target":"{postgres=X/postgres,service_role=X/postgres}","revoke_roles":["authenticated"],"grant_roles":[]},{"kind":"function","identity":"public.sync_scheduled_post_from_asset()","before":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}","target":"{postgres=X/postgres,service_role=X/postgres}","revoke_roles":["authenticated"],"grant_roles":[]},{"kind":"function","identity":"public.try_uuid(t text)","before":"{postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}","target":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}","revoke_roles":["anon"],"grant_roles":[]}]'::jsonb;
  item record;
  object_oid oid;
  actual_acl text;
  role_name text;
  count_functions integer := 0;
  count_relations integer := 0;
BEGIN
  -- Validate every before-state before changing a privilege.
  FOR item IN SELECT * FROM jsonb_to_recordset(targets) AS x(
    kind text, identity text, before text, target text, revoke_roles text[], grant_roles text[]) LOOP
    IF item.kind = 'function' THEN
      SELECT p.oid,p.proacl::text INTO object_oid,actual_acl
        FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
       WHERE format('%I.%I(%s)',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid))=item.identity;
      IF object_oid IS NULL OR actual_acl IS DISTINCT FROM item.before THEN
        RAISE EXCEPTION 'ACL precondition changed for function %',item.identity;
      END IF;
      count_functions := count_functions+1;
    ELSIF item.kind = 'relation' THEN
      SELECT c.oid,c.relacl::text INTO object_oid,actual_acl
        FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
       WHERE format('%I.%I',n.nspname,c.relname)=item.identity;
      IF object_oid IS NULL OR actual_acl IS DISTINCT FROM item.before THEN
        RAISE EXCEPTION 'ACL precondition changed for relation %',item.identity;
      END IF;
      count_relations := count_relations+1;
    ELSE RAISE EXCEPTION 'Unexpected ACL object kind'; END IF;
  END LOOP;
  IF count_functions<>192 OR count_relations<>3 THEN
    RAISE EXCEPTION 'ACL target count changed: % functions, % relations',count_functions,count_relations;
  END IF;
  FOR item IN SELECT * FROM jsonb_to_recordset(targets) AS x(
    kind text, identity text, before text, target text, revoke_roles text[], grant_roles text[]) LOOP
    IF item.kind='function' THEN
      SELECT p.oid INTO object_oid FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
       WHERE format('%I.%I(%s)',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid))=item.identity;
      FOREACH role_name IN ARRAY item.revoke_roles LOOP
        EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM %I',object_oid::regprocedure,role_name);
      END LOOP;
      FOREACH role_name IN ARRAY item.grant_roles LOOP
        EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO %I',object_oid::regprocedure,role_name);
      END LOOP;
    ELSE
      SELECT c.oid INTO object_oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
       WHERE format('%I.%I',n.nspname,c.relname)=item.identity;
      FOREACH role_name IN ARRAY item.revoke_roles LOOP
        EXECUTE format('REVOKE ALL PRIVILEGES ON TABLE %s FROM %I',object_oid::regclass,role_name);
      END LOOP;
      FOREACH role_name IN ARRAY item.grant_roles LOOP
        EXECUTE format('GRANT ALL PRIVILEGES ON TABLE %s TO %I',object_oid::regclass,role_name);
      END LOOP;
    END IF;
  END LOOP;
END
$acl$;
COMMIT;
